    if (!expectedSet.has(reviewId)) throw new Error('unknown extraction reviewId: ' + reviewId);
    if (extractionIds.has(reviewId)) throw new Error('duplicate extraction reviewId: ' + reviewId);
    extractionIds.add(reviewId);
